import{_ as t,o as a,c as s,ak as o}from"./chunks/framework.WEfAUR5x.js";const u=JSON.parse('{"title":"Endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"guide/endpoints.md","filePath":"guide/endpoints.md","lastUpdated":1780002933000}'),d={name:"guide/endpoints.md"};function i(n,e,r,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to “Endpoints”">​</a></h1><p>Pika lets an operator open additional HTTP or HTTPS ports that expose configuration data either directly, from an External resource, or in a shape other tools already understand — so existing clients (consul-template, spring-cloud-config consumers, custom apps) can keep talking to pika without changing their code.</p><p>Four modes are supported today:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What it does</th></tr></thead><tbody><tr><td><code>static</code></td><td>Direct <code>/data/{key}</code> style config response. No Go template and no compatibility envelope.</td></tr><tr><td><code>consul</code></td><td>Read-only Consul KV compatibility shim. Mounts <code>{base_path}/v1/kv/{key}</code>.</td></tr><tr><td><code>external</code></td><td>Direct read from one configured External resource. <code>{base_path}/{path}</code> maps to provider path.</td></tr><tr><td><code>custom</code></td><td>User-authored Go-template response modifier. Pika resolves the config, you shape the answer.</td></tr></tbody></table><p>Each endpoint owns its own TCP listener (<code>host:port</code>), TLS setting, and auth setting. Listeners are reconciled live: every save in the <strong>Settings → Endpoints</strong> panel diffs the desired list against what&#39;s running and starts/stops sockets accordingly.</p><h2 id="request-pipeline" tabindex="-1">Request pipeline <a class="header-anchor" href="#request-pipeline" aria-label="Permalink to “Request pipeline”">​</a></h2><p>Each request flows through three configurable stages, in order:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>client -&gt; [1. Auth] -&gt; [2. Request rules] -&gt; [3. Mode shim] -&gt; response</span></span></code></pre></div><ol><li><strong>Auth</strong> — <code>none</code>, <code>bearer_token</code>, or <code>static_token</code> (see below). Failed auth never reaches stage 2 or 3.</li><li><strong>Request rules</strong> — optional ordered list of declarative rules that can <code>allow</code>, <code>block</code>, or modify the request (set/del header, set/del query, rewrite path) before it hits the shim.</li><li><strong>Mode shim</strong> — direct config response, External resource read, Consul KV shim, or custom Go-template response. Sees the post-modify request.</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>Open <strong>Settings → Endpoints</strong>. Click <strong>+ New endpoint</strong> and fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td>Name</td><td>yes</td><td>Operator label. No uniqueness constraint.</td></tr><tr><td>Enabled</td><td>yes</td><td>Off means the configuration is kept but no socket is bound.</td></tr><tr><td>Listen host</td><td>yes</td><td>Default <code>0.0.0.0</code>. Use <code>127.0.0.1</code> to expose only on loopback.</td></tr><tr><td>Listen port</td><td>yes</td><td>Any free TCP port. Must not collide with the main pika port.</td></tr><tr><td>Base path</td><td>yes</td><td>URL prefix. Default <code>/</code>. Must start with <code>/</code> and have no trailing <code>/</code>.</td></tr><tr><td>HTTPS</td><td>no</td><td>New UI-created endpoints default to HTTPS using Settings → Certificates. Existing endpoints without a TLS block remain HTTP-only.</td></tr><tr><td>Mode</td><td>yes</td><td><code>static</code>, <code>consul</code>, <code>external</code>, or <code>custom</code>.</td></tr><tr><td>Auth</td><td>yes</td><td><code>none</code>, <code>bearer_token</code>, or <code>static_token</code>. See below.</td></tr></tbody></table><p>Configurations are persisted in the singleton settings document; static tokens are encrypted at rest by the same envelope that seals other secrets in Pika.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>none</code></td><td>No authentication. The listener serves anyone who can reach it.</td></tr><tr><td><code>bearer_token</code></td><td>Requires <code>Authorization: Bearer &lt;token&gt;</code> matching any pika API token with the <code>files.read</code> capability. Same tokens used by <code>/data/*</code>.</td></tr><tr><td><code>static_token</code></td><td>Compares the configured header (default <code>X-Pika-Token</code>; can be changed to <code>X-Consul-Token</code>, <code>Authorization</code>, etc.) in constant time against a small list of tokens. Send the raw token value, without <code>Bearer</code>.</td></tr></tbody></table><p>Static tokens are sealed at rest — when you re-open an endpoint in the UI the field comes back empty; leaving it empty preserves the previously-stored tokens, an explicit empty list clears them.</p><blockquote><p><strong>Operator tip.</strong> <code>none</code> is the simplest mode and is fine on a private network or behind a fronting reverse proxy that does its own auth. Treat it as &quot;this listener is publicly readable&quot; and design the rest of your network controls accordingly.</p></blockquote><h2 id="request-rules" tabindex="-1">Request rules <a class="header-anchor" href="#request-rules" aria-label="Permalink to “Request rules”">​</a></h2><p>The request-rules stage runs after authentication and before the mode shim. It is an ordered list of declarative rules — no templates, no JSON to hand-author. The editor in <strong>Settings → Endpoints</strong> lets you add rows, pick a matcher and one or more actions from dropdowns, and reorder rules with ↑/↓ buttons.</p><p>Use <strong>Test draft rules</strong> in the editor to run the unsaved rule list through the backend evaluator. It accepts a method, path (including optional query string), and headers, then shows matched rules, actions, and the final request shape the shim would see.</p><h3 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to “Evaluation”">​</a></h3><p>Rules are walked top-to-bottom for every request:</p><ul><li>A rule <strong>matches</strong> when every populated entry in its <code>when</code> block matches the current request (AND semantics). An empty <code>when</code> matches every request.</li><li>Each matching rule can run one or more actions in order.</li><li><code>allow</code> and <code>block</code> are <strong>terminal</strong> — they short-circuit evaluation. <code>block</code> writes the configured response; <code>allow</code> forwards to the shim immediately. Later actions in the same rule do not run.</li><li><code>set_header</code>, <code>del_header</code>, <code>set_query</code>, <code>del_query</code>, <code>set_path</code>, and <code>replace_path</code> are <strong>modify</strong> actions — they mutate the request and let evaluation continue with the next action, then the next rule. The shim sees the post-modify request.</li><li>If no rule terminates, the request falls through to the shim (implicit default-allow). Same convention as a firewall whose tail is an implicit ACCEPT.</li></ul><p>A rule with <code>enabled: false</code> is skipped entirely, but kept in the list so an operator can flip it on/off without losing the configuration.</p><h3 id="matchers-when" tabindex="-1">Matchers (<code>when</code>) <a class="header-anchor" href="#matchers-when" aria-label="Permalink to “Matchers (when)”">​</a></h3><p>Pick one matcher per rule. Need two matchers AND-ed? Add two rules — one modify, one terminal — or split into rule chains via stacked modifies.</p><table tabindex="0"><thead><tr><th>Matcher</th><th>Fires when …</th></tr></thead><tbody><tr><td><code>any request</code></td><td>Always. Useful as a default-deny tail (<code>when=any, then=block</code>).</td></tr><tr><td><code>method</code></td><td>Request method equals the configured value (case insensitive).</td></tr><tr><td><code>path equals</code></td><td>URL path equals the configured string exactly.</td></tr><tr><td><code>path prefix</code></td><td>URL path starts with the configured string.</td></tr><tr><td><code>header equals</code></td><td>The named header&#39;s first value equals the configured value.</td></tr><tr><td><code>header present</code></td><td>The named header is set and has a non-empty value.</td></tr><tr><td><code>header absent</code></td><td>The named header is missing or only has empty values.</td></tr><tr><td><code>query equals</code></td><td>The named query parameter&#39;s first value equals the configured value.</td></tr><tr><td><code>query present</code></td><td>The named query parameter is set and non-empty.</td></tr><tr><td><code>query absent</code></td><td>The named query parameter is missing or empty.</td></tr></tbody></table><p>Header names are case-insensitive in the matcher (canonical form is used internally), so <code>X-Tenant</code> and <code>x-tenant</code> behave the same. Header values are case-sensitive.</p><h3 id="actions-then" tabindex="-1">Actions (<code>then</code>) <a class="header-anchor" href="#actions-then" aria-label="Permalink to “Actions (then)”">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><code>allow</code></td><td>Forward to the shim immediately. Stops evaluation.</td></tr><tr><td><code>block</code></td><td>Reply with the configured status (default 403), body, and content-type. Stops evaluation.</td></tr><tr><td><code>set_header</code></td><td>Set a request header (overwrites existing values). Continues evaluation.</td></tr><tr><td><code>del_header</code></td><td>Remove a request header. Continues evaluation.</td></tr><tr><td><code>set_query</code></td><td>Set a query parameter. Continues evaluation.</td></tr><tr><td><code>del_query</code></td><td>Remove a query parameter. Continues evaluation.</td></tr><tr><td><code>set_path</code></td><td>Replace the whole URL path with a literal value. Must start with <code>/</code>. Not regex/capture based. Continues evaluation.</td></tr><tr><td><code>replace_path</code></td><td>Regex-replace the URL path. Uses Go regexp syntax and <code>$1</code> / <code>$name</code> capture replacements. Optional capture transforms can replace literal text inside a capture before expansion. Continues evaluation.</td></tr></tbody></table><p><code>set_path</code> is intentionally simple: it does not run a regex and it does not preserve an unmatched suffix. If a rule matches <code>/legacy/app</code>, then <code>set_path = /myapp/config</code> means the shim receives exactly <code>/myapp/config</code>.</p><p>Use <code>replace_path</code> when you want capture groups. The regex runs against the whole current path, and the replacement becomes the new path. If the replacement does not start with <code>/</code>, Pika prefixes it. When text follows a capture directly, prefer <code>\${1}</code> over <code>$1</code> so Go&#39;s regexp replacement parser does not treat the following characters as part of the capture name.</p><p>Capture transforms are optional literal string replacements applied to a selected capture before the final replacement is expanded. The capture can be a number (<code>1</code>) or a named capture (<code>tail</code>); <code>find</code> must be non-empty and is not a regex.</p><h3 id="example-recipes" tabindex="-1">Example recipes <a class="header-anchor" href="#example-recipes" aria-label="Permalink to “Example recipes”">​</a></h3><p><strong>Require a tenant header on every request</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>then</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>header absent: <code>X-Tenant</code></td><td>block — status 401, body &quot;missing tenant&quot;</td></tr></tbody></table><p><strong>Force every request onto the prod variant</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>then</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>any</td><td>set_query — <code>variant</code> = <code>prod</code></td></tr></tbody></table><p><strong>Rewrite a legacy path</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>then</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>path equals: <code>/v1/kv/legacy</code></td><td>set_path — <code>/v1/kv/myapp/config</code></td></tr></tbody></table><p>This is a full replacement: a request for <code>/v1/kv/legacy</code> reaches the shim as <code>/v1/kv/myapp/config</code>. It is not <code>/v1/kv/&lt;regex&gt;</code> rewriting; dynamic capture groups are not supported by this action.</p><p><strong>Regex rewrite a legacy prefix</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>then</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>path starts with: <code>/legacy/</code></td><td>replace_path — pattern <code>^/legacy/(.*)$</code>, replacement <code>/$1</code></td></tr></tbody></table><p>This keeps the suffix dynamically. A request for <code>/legacy/myapp/config</code> reaches the shim as <code>/myapp/config</code>. In static config-data mode with <code>base_path=/</code>, that resolves the same key as <code>/data/myapp/config</code>.</p><p><strong>Convert a two-segment path to an underscore key</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>then</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>path starts with: <code>/</code></td><td>replace_path — pattern <code>^/([^/]+)/([^/]+)$</code>, replacement <code>/\${1}_\${2}</code></td></tr></tbody></table><p>This turns <code>/myapp/config</code> into <code>/myapp_config</code>. In static config-data mode with <code>base_path=/</code>, that resolves <code>/data/myapp_config</code>.</p><p><strong>Transform a captured suffix</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>then</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>path starts with: <code>/legacy/</code></td><td>replace_path — pattern <code>^/legacy/(?P&lt;tail&gt;.*)$</code>, replacement <code>/legacy/\${tail}</code>, transform capture <code>tail</code>: find <code>/</code>, replace <code>-</code></td></tr></tbody></table><p>This turns <code>/legacy/1/2/3/4/5/6</code> into <code>/legacy/1-2-3-4-5-6</code> in one action. The regex selects the suffix as <code>tail</code>; the capture transform edits only that captured text before <code>\${tail}</code> is inserted into the replacement.</p><p><strong>Chain multiple actions in one rule</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>actions</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>path starts with: <code>/legacy/</code></td><td>1. replace_path <code>^/legacy/(.*)$</code> → <code>/\${1}</code>; 2. replace_path <code>([^/]+)/</code> → <code>\${1}_</code></td></tr></tbody></table><p>This turns <code>/legacy/myapp/config</code> into <code>/myapp_config</code> in a single rule: first remove the legacy prefix, then replace every internal <code>/</code> after a segment with <code>_</code>. The actions run top-to-bottom; if one of them were <code>allow</code> or <code>block</code>, evaluation would stop there.</p><p><strong>Admin override + default-deny</strong></p><table tabindex="0"><thead><tr><th>#</th><th>enabled</th><th>when</th><th>then</th></tr></thead><tbody><tr><td>1</td><td>yes</td><td>header equals: <code>X-Admin</code> = <code>yes</code></td><td>allow</td></tr><tr><td>2</td><td>yes</td><td>any</td><td>block — status 403</td></tr></tbody></table><p>Rule 1 lets admin requests through; rule 2 catches everything else.</p><h2 id="mode-static-config-data" tabindex="-1">Mode: Static config data <a class="header-anchor" href="#mode-static-config-data" aria-label="Permalink to “Mode: Static config data”">​</a></h2><p>Static mode is the plain <code>/data/{key}</code> equivalent for Endpoints. The path tail after the endpoint&#39;s base path is resolved as a pika config key, then the resolved bytes are written directly with the same content-type and format conversion rules as <code>/data/*</code>. It does not run a Go template and does not wrap the response in a Consul envelope.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET {base_path}/{key} [?variant=] [?version=] [?format=]</span></span></code></pre></div><p>For example, with <code>base_path=/cfg</code>, this request:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:9090/cfg/myapp/config</span></span></code></pre></div><p>behaves like:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://localhost:8080/data/myapp/config</span></span></code></pre></div><h3 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to “Query parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>variant</code></td><td>Pika variant name (e.g. <code>prod</code>, <code>staging</code>).</td></tr><tr><td><code>version</code></td><td>Integer or semver, same semantics as <code>/data/*</code>.</td></tr><tr><td><code>format</code></td><td>Convert output to a different format (<code>json</code>, <code>yaml</code>, <code>toml</code>).</td></tr></tbody></table><h3 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to “Response”">​</a></h3><p>The body is the resolved config file bytes. <code>Content-Type</code> is chosen from the resolved or converted format:</p><table tabindex="0"><thead><tr><th>Format</th><th><code>Content-Type</code></th></tr></thead><tbody><tr><td>JSON</td><td><code>application/json</code></td></tr><tr><td>YAML</td><td><code>application/x-yaml</code></td></tr><tr><td>TOML</td><td><code>application/toml</code></td></tr><tr><td>Other</td><td><code>application/octet-stream</code></td></tr></tbody></table><h3 id="status-codes" tabindex="-1">Status codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to “Status codes”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>200</td><td>OK.</td></tr><tr><td>400</td><td>Bad request — invalid format conversion or config error.</td></tr><tr><td>401</td><td>Auth missing or invalid (when auth mode is not <code>none</code>).</td></tr><tr><td>404</td><td>Key (or variant / version) not found.</td></tr><tr><td>405</td><td>Non-GET request.</td></tr></tbody></table><p>Request rules still run before the static response. For example, you can require <code>X-Tenant</code>, force <code>?variant=prod</code>, or rewrite a legacy path before the config key is resolved.</p><h2 id="mode-external-resource" tabindex="-1">Mode: External resource <a class="header-anchor" href="#mode-external-resource" aria-label="Permalink to “Mode: External resource”">​</a></h2><p>External mode reads directly from one configured External resource. It does not go through <code>/data/*</code>, config inheritance, or file rendering. The path tail after the endpoint&#39;s base path is passed to the selected provider as its resource-specific path.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET {base_path}/{path} [?version=]</span></span></code></pre></div><p>For example, with <code>base_path=/vault</code> and <code>resource=prod-vault</code>:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:9090/vault/apps/api/db</span></span></code></pre></div><p>behaves like an admin External read of resource <code>prod-vault</code> at path <code>apps/api/db</code>.</p><h3 id="resource-selection" tabindex="-1">Resource selection <a class="header-anchor" href="#resource-selection" aria-label="Permalink to “Resource selection”">​</a></h3><p>Pick the External resource in <strong>Settings → Endpoints → Mode → External resource</strong>. The dropdown lists the resources already configured in <strong>Settings → External resources</strong>.</p><h3 id="response-1" tabindex="-1">Response <a class="header-anchor" href="#response-1" aria-label="Permalink to “Response”">​</a></h3><p>The endpoint returns the provider entry&#39;s raw bytes and content-type when available. For structured providers such as Vault, Kubernetes, Consul, etcd, AWS, GCP, and Azure, that is typically JSON. For HTTP external resources, it is the HTTP response body returned by the configured upstream.</p><h3 id="query-parameters-1" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters-1" aria-label="Permalink to “Query parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>Read a provider-specific historical version when the backend supports it.</td></tr></tbody></table><p>If the selected backend does not support versions, <code>?version=</code> returns a bad request instead of falling back silently.</p><p>Request rules still run first, so you can rewrite <code>/legacy/(.*)</code> to <code>/$1</code>, force a tenant header, or block disallowed paths before the external provider sees the path.</p><h2 id="mode-consul-kv" tabindex="-1">Mode: Consul KV <a class="header-anchor" href="#mode-consul-kv" aria-label="Permalink to “Mode: Consul KV”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET {base_path}/v1/kv/{key} [?raw] [?variant=] [?version=] [?format=]</span></span></code></pre></div><p><code>{key}</code> is a pika config path (e.g. <code>myapp/config</code>). The shim also accepts the bare <code>/v1/kv/...</code> prefix in addition to the configured base path so clients that don&#39;t include the prefix still work.</p><h3 id="query-parameters-2" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters-2" aria-label="Permalink to “Query parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>raw</code></td><td>Return raw bytes instead of the Consul JSON envelope.</td></tr><tr><td><code>variant</code></td><td>Pika variant name (e.g. <code>prod</code>, <code>staging</code>).</td></tr><tr><td><code>version</code></td><td>Integer or semver, same semantics as <code>/data/*</code>.</td></tr><tr><td><code>format</code></td><td>Convert output to a different format (<code>json</code>, <code>yaml</code>, <code>toml</code>).</td></tr></tbody></table><h3 id="default-response" tabindex="-1">Default response <a class="header-anchor" href="#default-response" aria-label="Permalink to “Default response”">​</a></h3><p>A JSON array with one Consul-shaped entry. <code>Value</code> is base64-encoded, matching Consul&#39;s behaviour:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;CreateIndex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ModifyIndex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;LockIndex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp/config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Flags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ZGF0YWJhc2U6CiAgaG9zdDogbG9jYWxob3N0Cg==&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Session&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="raw-response" tabindex="-1"><code>?raw</code> response <a class="header-anchor" href="#raw-response" aria-label="Permalink to “?raw response”">​</a></h3><p>Returns the raw config bytes with the appropriate <code>Content-Type</code>:</p><table tabindex="0"><thead><tr><th>Format</th><th><code>Content-Type</code></th></tr></thead><tbody><tr><td>JSON</td><td><code>application/json</code></td></tr><tr><td>YAML</td><td><code>application/x-yaml</code></td></tr><tr><td>TOML</td><td><code>application/toml</code></td></tr><tr><td>Other</td><td><code>application/octet-stream</code></td></tr></tbody></table><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Raw bytes — looks just like Consul KV</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:9090/consul/v1/kv/myapp/config?raw</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Raw bytes, converted to JSON, prod variant</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:9090/consul/v1/kv/myapp/config?raw&amp;variant=prod&amp;format=json&quot;</span></span></code></pre></div><h3 id="status-codes-1" tabindex="-1">Status codes <a class="header-anchor" href="#status-codes-1" aria-label="Permalink to “Status codes”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>200</td><td>OK.</td></tr><tr><td>400</td><td>Bad request — typically a malformed query parameter.</td></tr><tr><td>401</td><td>Auth missing or invalid (when auth mode is not <code>none</code>).</td></tr><tr><td>404</td><td>Key (or variant / version) not found. Empty body.</td></tr></tbody></table><p>The 404-with-empty-body behaviour matches Consul KV — a number of clients depend on it.</p><h3 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h3><ul><li><strong>Read-only.</strong> No <code>PUT</code> / <code>DELETE</code> / <code>/v1/txn</code>. Use <code>/api/v1/file/...</code> from the admin port for writes.</li><li><strong>No watch / blocking queries.</strong> <code>?wait=</code> / <code>?index=</code> are accepted but ignored. Long-poll consumers fall back to immediate responses.</li><li><strong>No ACL endpoints.</strong> Use the endpoint&#39;s own <code>auth</code> setting instead.</li></ul><p>For most read-only library use (consul-template, frameworks that pull config from Consul KV at startup), this is enough.</p><h2 id="mode-custom-go-template" tabindex="-1">Mode: Custom Go template <a class="header-anchor" href="#mode-custom-go-template" aria-label="Permalink to “Mode: Custom Go template”">​</a></h2><p>Custom mode lets you author a Go <code>text/template</code> that produces the response body — useful when the wire shape isn&#39;t Consul KV (etcd, Spring Cloud Config, a custom in-house contract, etc.).</p><h3 id="request-shape" tabindex="-1">Request shape <a class="header-anchor" href="#request-shape" aria-label="Permalink to “Request shape”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET {base_path}/{key} [?raw] [?variant=] [?version=] [?format=]</span></span></code></pre></div><p>The path tail after <code>base_path</code> becomes the template&#39;s <code>.Key</code> value. The query parameters above pass through to the template as <code>.Variant</code>, <code>.Version</code>, <code>.Raw</code>, <code>.Format</code>.</p><h3 id="template-variables" tabindex="-1">Template variables <a class="header-anchor" href="#template-variables" aria-label="Permalink to “Template variables”">​</a></h3><p>The template runs against a curated input map:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>.Key</code></td><td>string</td><td>Path tail (the resolved pika key).</td></tr><tr><td><code>.Variant</code></td><td>string</td><td>Variant query param, or <code>&quot;&quot;</code>.</td></tr><tr><td><code>.Version</code></td><td>string</td><td>Version query param, or <code>&quot;&quot;</code>.</td></tr><tr><td><code>.Raw</code></td><td>bool</td><td>True when <code>?raw</code> is present.</td></tr><tr><td><code>.Format</code></td><td>string</td><td>Requested format (after <code>?format=</code> override).</td></tr><tr><td><code>.Data</code></td><td>[]byte</td><td>Resolved configuration bytes.</td></tr><tr><td><code>.DataString</code></td><td>string</td><td>String view of <code>.Data</code>.</td></tr><tr><td><code>.DataB64</code></td><td>string</td><td>Base64-encoded <code>.Data</code> — handy for Consul-style envelopes.</td></tr><tr><td><code>.Found</code></td><td>bool</td><td><code>false</code> when the underlying key was not found.</td></tr><tr><td><code>.ResolvedFormat</code></td><td>string</td><td>Format pika actually produced for <code>.Data</code>.</td></tr><tr><td><code>.Now</code></td><td>time.Time</td><td>Current server time (UTC).</td></tr></tbody></table><p>The funcmap is curated: <code>b64</code>, <code>b64dec</code>, <code>upper</code>, <code>lower</code>, <code>trim</code>, <code>join</code>, <code>split</code>, <code>rfc3339</code>, <code>unix</code>. Filesystem, environment, and command-execution helpers are <strong>not</strong> exposed.</p><h3 id="response-2" tabindex="-1">Response <a class="header-anchor" href="#response-2" aria-label="Permalink to “Response”">​</a></h3><p>The template output becomes the HTTP body. <code>Content-Type</code> and the status returned when the key is missing are configured per endpoint:</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>content_type</code></td><td><code>application/octet-stream</code></td><td>Sent verbatim as the response <code>Content-Type</code>.</td></tr><tr><td><code>status_on_missing</code></td><td><code>404</code></td><td>HTTP status when <code>.Found</code> is false.</td></tr><tr><td><code>allow_format_override</code></td><td><code>false</code></td><td>When true, the client may pass <code>?format=</code> to convert data.</td></tr></tbody></table><h3 id="example-consul-kv-envelope-verbatim-of-the-built-in-shim" tabindex="-1">Example: Consul KV envelope (verbatim of the built-in shim) <a class="header-anchor" href="#example-consul-kv-envelope-verbatim-of-the-built-in-shim" aria-label="Permalink to “Example: Consul KV envelope (verbatim of the built-in shim)”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;Key&quot;: &quot;{{ .Key }}&quot;,</span></span>
<span class="line"><span>    &quot;Value&quot;: &quot;{{ .DataB64 }}&quot;,</span></span>
<span class="line"><span>    &quot;CreateIndex&quot;: 0,</span></span>
<span class="line"><span>    &quot;ModifyIndex&quot;: 0,</span></span>
<span class="line"><span>    &quot;LockIndex&quot;: 0,</span></span>
<span class="line"><span>    &quot;Flags&quot;: 0,</span></span>
<span class="line"><span>    &quot;Session&quot;: &quot;&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>]</span></span></code></pre></div><h3 id="example-spring-cloud-config-style-flat-yaml" tabindex="-1">Example: Spring Cloud Config-style flat YAML <a class="header-anchor" href="#example-spring-cloud-config-style-flat-yaml" aria-label="Permalink to “Example: Spring Cloud Config-style flat YAML”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{{ if .Found -}}</span></span>
<span class="line"><span>{{ .DataString }}</span></span>
<span class="line"><span>{{- else -}}</span></span>
<span class="line"><span># config &#39;{{ .Key }}&#39; not found</span></span>
<span class="line"><span>{{- end }}</span></span></code></pre></div><p>Set <code>content_type</code> to <code>application/x-yaml</code> and <code>status_on_missing</code> to <code>200</code> if the client expects a 200 with a marker comment instead of a 404.</p><h3 id="limitations-1" tabindex="-1">Limitations <a class="header-anchor" href="#limitations-1" aria-label="Permalink to “Limitations”">​</a></h3><ul><li><strong>Read-only.</strong> GET only; non-GET requests return 405.</li><li><strong>Template is stateless.</strong> No sessions, no per-request storage. Use pika&#39;s variants/versions to model environment differences.</li><li><strong>No streaming.</strong> The whole body is rendered into memory before write. Large configs are fine; multi-gigabyte payloads are not.</li></ul><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to “Diagnostics”">​</a></h2><p>The Settings → Endpoints panel shows a live status badge per entry (<code>running</code> / <code>bind failed</code> / <code>disabled</code> / <code>pending</code>) sourced from <code>GET /api/v1/public-endpoints/status</code>. A click on the <strong>▶</strong> button on any row opens a probe: it issues a synthetic GET through the same handler the live listener serves and returns status + headers + body. The probe panel includes a &quot;Request headers&quot; editor so you can supply auth tokens, tenant headers matched by your request rules, or anything else the live chain inspects — useful for validating a rule list end-to-end before pointing real clients at it.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /api/v1/public-endpoints/status              # list every endpoint + runtime state</span></span>
<span class="line"><span>POST /api/v1/public-endpoints/{id}/test          # probe a single endpoint (admin auth)</span></span></code></pre></div><p>The probe endpoint constructs the same handler chain (auth + request rules + shim) the live listener uses. If you&#39;ve set <code>auth.mode = &quot;bearer_token&quot;</code> or <code>&quot;static_token&quot;</code>, add the same request header in the probe panel&#39;s <strong>Request headers</strong> editor, or pass it in the API body as <code>headers</code>.</p>`,126)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
